-- Product Learning Sync checked: deterministic reminders, per-user opt-in and current authorization before push.
create table public.sv_notification_preferences(company_id uuid not null,user_id uuid not null,data jsonb not null default '{"assignment":true,"followup":true,"sla":true,"push":false,"quietStart":21,"quietEnd":9}',revision bigint not null default 0,primary key(company_id,user_id),foreign key(company_id,user_id)references public.sv_memberships(company_id,user_id));
create table public.sv_notifications(company_id uuid not null,user_id uuid not null,id uuid not null default gen_random_uuid(),source_key text not null,brand_id text not null,kind text not null check(kind in('assignment','followup','sla')),title text not null,href text not null,state text not null default 'open'check(state in('open','done','expired')),snoozed_until timestamptz,revision bigint not null default 0,created_at timestamptz not null default now(),primary key(company_id,user_id,id),unique(company_id,user_id,source_key),foreign key(company_id,user_id)references public.sv_memberships(company_id,user_id));
create index sv_notifications_page on public.sv_notifications(company_id,user_id,created_at desc,id desc);
create table public.sv_push_devices(company_id uuid not null,user_id uuid not null,id uuid not null default gen_random_uuid(),endpoint text not null,p256dh text not null,auth text not null,label text not null check(length(label)between 1 and 80),active boolean not null default true,created_at timestamptz not null default now(),primary key(company_id,user_id,id),unique(company_id,user_id,endpoint),foreign key(company_id,user_id)references public.sv_memberships(company_id,user_id));
create unique index sv_push_active_endpoint on public.sv_push_devices(endpoint)where active;
create table public.sv_push_attempts(company_id uuid not null,user_id uuid not null,notification_id uuid not null,device_id uuid not null,state text not null check(state in('dispatching','accepted','failed','unknown')),reason text,created_at timestamptz not null default now(),primary key(company_id,user_id,notification_id,device_id),foreign key(company_id,user_id,notification_id)references public.sv_notifications(company_id,user_id,id),foreign key(company_id,user_id,device_id)references public.sv_push_devices(company_id,user_id,id));
create function smartvolt_private.notification_candidates(p_company uuid,p_actor uuid)returns table(source_key text,brand_id text,kind text,title text,href text)language sql stable security invoker set search_path=''as $$
 with actor as(select role from public.sv_memberships where company_id=p_company and user_id=p_actor and status='active'and role<>'viewer'),
 facts as(
 select 'followup:'||f.id||':'||f.due_at source_key,f.brand_id,'followup'kind,f.title title,'/crm?'||'provider='||f.provider||'&thread='||f.thread_id href
 from public.sv_followup_tasks f where f.company_id=p_company and f.status='open'and f.due_at<=statement_timestamp()and(f.owner_id=p_actor or(f.owner_id is null and exists(select 1 from actor where role in('owner','manager'))))
 union all select 'sla:'||q.episode_id,q.brand_id,'sla','客人等待真人回覆','/crm?provider='||q.provider||'&thread='||q.thread_id from smartvolt_private.sla_queue q where q.company_id=p_company and q.response_due_at<=statement_timestamp()and(q.assignee_id=p_actor or exists(select 1 from actor where role in('owner','manager')))
 union all select 'assignment:event:'||e.seq,e.brand_id,'assignment','有新客人交咗畀你','/crm?provider='||(e.detail->>'provider')||'&thread='||(e.detail->>'threadId')from public.sv_customer_events e where e.company_id=p_company and e.kind='routing-assigned'and e.detail->>'ownerId'=p_actor::text and e.created_at>statement_timestamp()-interval '30 days'
 union all select 'assignment:wa:'||a.command_id,l.brand_id,'assignment','有對話交咗畀你','/crm?provider=whatsapp&thread='||a.thread_id from public.sv_wa_thread_activity a join public.sv_customer_threads l on l.company_id=a.company_id and l.provider='whatsapp'and l.thread_id=a.thread_id where a.company_id=p_company and a.next->>'assignee_id'=p_actor::text and a.previous->'assignee_id'is distinct from a.next->'assignee_id'and a.created_at>statement_timestamp()-interval '30 days'
 union all select 'assignment:meta:'||a.command_id,l.brand_id,'assignment','有對話交咗畀你','/crm?provider=meta&thread='||a.thread_id from public.sv_meta_thread_activity a join public.sv_customer_threads l on l.company_id=a.company_id and l.provider='meta'and l.thread_id=a.thread_id where a.company_id=p_company and a.next->>'assignee_id'=p_actor::text and a.previous->'assignee_id'is distinct from a.next->'assignee_id'and a.created_at>statement_timestamp()-interval '30 days'
 union all select 'sales:'||e.source_id||':'||e.follow_up_at,e.brand_id,'followup','官網查詢到咗跟進時間','/crm/sales'from public.sv_sales_enquiries e where e.company_id=p_company and e.owner_id=p_actor and e.status<>'closed'and e.follow_up_at<=statement_timestamp()
 )select f.source_key,f.brand_id,f.kind,f.title,'/company/'||p_company||f.href from facts f where exists(select 1 from actor)and smartvolt_private.member_has_product(p_company,p_actor,'crm')and smartvolt_private.member_brand_allowed(p_company,p_actor,f.brand_id)
$$;
create function public.sv_notification_sync(p_company uuid,p_actor uuid)returns void language plpgsql security invoker set search_path=''as $$begin
 perform public.sv_authorize(p_company,p_actor,'crm');
 insert into public.sv_notification_preferences(company_id,user_id)values(p_company,p_actor)on conflict do nothing;
 insert into public.sv_notifications(company_id,user_id,source_key,brand_id,kind,title,href)
 select p_company,p_actor,c.source_key,c.brand_id,c.kind,c.title,c.href from smartvolt_private.notification_candidates(p_company,p_actor)c where not exists(select 1 from public.sv_notifications n where n.company_id=p_company and n.user_id=p_actor and n.source_key=c.source_key)and coalesce((select(data->>c.kind)::boolean from public.sv_notification_preferences where company_id=p_company and user_id=p_actor),true)order by c.source_key limit 200 on conflict do nothing;
 update public.sv_notifications n set state='expired',revision=revision+1 where n.company_id=p_company and n.user_id=p_actor and n.state='open'and not exists(select 1 from smartvolt_private.notification_candidates(p_company,p_actor)c where c.source_key=n.source_key);
end;$$;
create function public.sv_notification_read(p_company uuid,p_actor uuid,p_before timestamptz default null,p_id uuid default null)returns jsonb language plpgsql security invoker set search_path=''as $$begin
 perform public.sv_notification_sync(p_company,p_actor);
 return jsonb_build_object('preferences',(select jsonb_build_object('data',data,'revision',revision)from public.sv_notification_preferences where company_id=p_company and user_id=p_actor),
 'total',(select count(*)from public.sv_notifications where company_id=p_company and user_id=p_actor and state='open'and coalesce(snoozed_until,'epoch')<=statement_timestamp()and smartvolt_private.member_brand_allowed(p_company,p_actor,brand_id)),
 'rows',coalesce((select jsonb_agg(q order by q.created_at desc,q.id desc)from(select id,kind,title,href,state,snoozed_until,revision,created_at from public.sv_notifications where company_id=p_company and user_id=p_actor and state='open'and coalesce(snoozed_until,'epoch')<=statement_timestamp()and smartvolt_private.member_brand_allowed(p_company,p_actor,brand_id)and(p_before is null or(created_at,id)<(p_before,p_id))order by created_at desc,id desc limit 31)q),'[]'),
 'devices',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',label,'active',active,'created_at',created_at))from public.sv_push_devices where company_id=p_company and user_id=p_actor),'[]'));
end;$$;
create function public.sv_notification_action(p_company uuid,p_actor uuid,p_command uuid,p_kind text,p_data jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$declare r jsonb;rev bigint;begin
 perform public.sv_authorize(p_company,p_actor,'crm');
 r=smartvolt_private.action_replay(p_company,p_actor,p_command,'notification:'||p_kind,p_data);if r is not null then return r;end if;
 if p_kind='preferences'then
  insert into public.sv_notification_preferences(company_id,user_id)values(p_company,p_actor)on conflict do nothing;
  update public.sv_notification_preferences set data=p_data->'data',revision=revision+1 where company_id=p_company and user_id=p_actor and revision=(p_data->>'revision')::bigint;if not found then raise exception 'revision_conflict';end if;
 elsif p_kind in('done','snooze')then
  update public.sv_notifications set state=case when p_kind='done'then 'done'else state end,snoozed_until=case when p_kind='snooze'then(p_data->>'until')::timestamptz else snoozed_until end,revision=revision+1 where company_id=p_company and user_id=p_actor and id=(p_data->>'id')::uuid and revision=(p_data->>'revision')::bigint and smartvolt_private.member_brand_allowed(p_company,p_actor,brand_id);if not found then raise exception 'revision_conflict';end if;
 elsif p_kind='device'then
  if p_data->>'endpoint'!~'^https://(fcm.googleapis.com|updates.push.services.mozilla.com|web.push.apple.com)/'then raise exception 'invalid_push_endpoint';end if;
  if exists(select 1 from public.sv_push_devices where endpoint=p_data->>'endpoint'and(company_id,user_id)<>(p_company,p_actor)and active)then raise exception 'device_owner_changed';end if;
  if(select count(*)from public.sv_push_devices where company_id=p_company and user_id=p_actor and active)>=10 and not exists(select 1 from public.sv_push_devices where company_id=p_company and user_id=p_actor and endpoint=p_data->>'endpoint')then raise exception 'device_limit';end if;
  insert into public.sv_push_devices(company_id,user_id,endpoint,p256dh,auth,label)values(p_company,p_actor,p_data->>'endpoint',p_data->>'p256dh',p_data->>'auth',p_data->>'label')on conflict(company_id,user_id,endpoint)do update set active=true,p256dh=excluded.p256dh,auth=excluded.auth,label=excluded.label;
  insert into public.sv_notification_preferences(company_id,user_id,data)values(p_company,p_actor,'{"assignment":true,"followup":true,"sla":true,"push":true,"quietStart":21,"quietEnd":9}')on conflict(company_id,user_id)do update set data=jsonb_set(sv_notification_preferences.data,'{push}','true'),revision=sv_notification_preferences.revision+1;
 elsif p_kind='revoke'then update public.sv_push_devices set active=false where company_id=p_company and user_id=p_actor and id=(p_data->>'id')::uuid;if not found then raise exception 'device_missing';end if;
 else raise exception 'invalid_action';end if;
 r='{"saved":true}';insert into public.sv_action_receipts(company_id,command_id,actor_id,kind,data,result)values(p_company,p_command,p_actor,'notification:'||p_kind,p_data,r);return r;end;$$;
create function public.sv_push_claim(p_company uuid,p_actor uuid)returns jsonb language plpgsql security invoker set search_path=''as $$declare p jsonb;result jsonb;hour integer:=extract(hour from statement_timestamp()at time zone 'Asia/Hong_Kong');begin
 perform public.sv_authorize(p_company,p_actor,'crm');select data into p from public.sv_notification_preferences where company_id=p_company and user_id=p_actor;
 if not coalesce((p->>'push')::boolean,false)or((p->>'quietStart')::integer<>(p->>'quietEnd')::integer and(case when(p->>'quietStart')::integer<(p->>'quietEnd')::integer then hour>=(p->>'quietStart')::integer and hour<(p->>'quietEnd')::integer else hour>=(p->>'quietStart')::integer or hour<(p->>'quietEnd')::integer end))then return '[]';end if;
 with candidates as(select n.id notification_id,d.id device_id from public.sv_notifications n join public.sv_push_devices d on d.company_id=n.company_id and d.user_id=n.user_id and d.active where n.company_id=p_company and n.user_id=p_actor and n.state='open'and n.created_at>statement_timestamp()-interval '1 day'and coalesce(n.snoozed_until,'epoch')<=statement_timestamp()and coalesce((p->>n.kind)::boolean,false)and smartvolt_private.member_brand_allowed(p_company,p_actor,n.brand_id)and exists(select 1 from smartvolt_private.notification_candidates(p_company,p_actor)c where c.source_key=n.source_key)and not exists(select 1 from public.sv_push_attempts a where a.company_id=n.company_id and a.user_id=n.user_id and a.notification_id=n.id and a.device_id=d.id)order by n.created_at,n.id,d.id limit 20 for update of n skip locked),claimed as(insert into public.sv_push_attempts(company_id,user_id,notification_id,device_id,state)select p_company,p_actor,notification_id,device_id,'dispatching'from candidates on conflict do nothing returning *)select coalesce(jsonb_agg(jsonb_build_object('notificationId',a.notification_id,'deviceId',a.device_id,'endpoint',d.endpoint,'p256dh',d.p256dh,'auth',d.auth)), '[]')into result from claimed a join public.sv_push_devices d on d.company_id=a.company_id and d.user_id=a.user_id and d.id=a.device_id;return result;
end;$$;
create function public.sv_push_finish(p_company uuid,p_actor uuid,p_notification uuid,p_device uuid,p_state text,p_reason text,p_expired boolean)returns void language plpgsql security invoker set search_path=''as $$begin
 if p_state not in('accepted','failed','unknown')then raise exception 'invalid_state';end if;
 update public.sv_push_attempts set state=p_state,reason=left(p_reason,80)where company_id=p_company and user_id=p_actor and notification_id=p_notification and device_id=p_device and state='dispatching';
 if p_expired then update public.sv_push_devices set active=false where company_id=p_company and user_id=p_actor and id=p_device;end if;
end;$$;
do $$declare t text;f record;begin
 foreach t in array array['sv_notification_preferences','sv_notifications','sv_push_devices','sv_push_attempts']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select,insert,update on public.%I to service_role',t);end loop;
 for f in select oid::regprocedure signature from pg_proc where pronamespace in('public'::regnamespace,'smartvolt_private'::regnamespace)and proname in('notification_candidates','sv_notification_sync','sv_notification_read','sv_notification_action','sv_push_claim','sv_push_finish')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end;$$;
create table public.sv_notification_scan_state(company_id uuid primary key references public.sv_companies(id),after_user uuid);
create function public.sv_notification_members(p_company uuid)returns jsonb language plpgsql security invoker set search_path=''as $$declare cursor uuid;ids uuid[];begin
 insert into public.sv_notification_scan_state(company_id)values(p_company)on conflict do nothing;select after_user into cursor from public.sv_notification_scan_state where company_id=p_company for update;
 select array_agg(user_id order by user_id)into ids from(select user_id from public.sv_memberships where company_id=p_company and status='active'and role<>'viewer'and(cursor is null or user_id>cursor)and smartvolt_private.member_has_product(p_company,user_id,'crm')order by user_id limit 5)q;
 update public.sv_notification_scan_state set after_user=case when cardinality(ids)=5 then ids[5]end where company_id=p_company;return coalesce(to_jsonb(ids),'[]');end;$$;
alter table public.sv_notification_scan_state enable row level security;revoke all on public.sv_notification_scan_state from public,anon,authenticated,service_role;grant select,insert,update on public.sv_notification_scan_state to service_role;
revoke all on function public.sv_notification_members(uuid)from public,anon,authenticated;grant execute on function public.sv_notification_members(uuid)to service_role;
